import {createDemo,act,averageMoisture,zoneAdvice,isStale,movementReason,waterReason,assistantAnswer,importTelemetry,exportTelemetry,liveFresh} from './domain.js';
import {openStore,readState,saveState} from './storage.js';
import {createFarmerExperience,FARMER_PAGES} from './farmer.js';

const paths={
  home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
  field:'M3 4h18v16H3ZM3 10h18M3 15h18M11 4v16',
  alert:'m12 3 10 18H2Zm0 5v5m0 4v.1',
  rover:'M4 9h16v8H4Zm3-4h10v4M8 17v3m8-3v3M7 12v1m10-1v1M2 11v4m20-4v4',
  voice:'M9 4a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0Zm-3 7a6 6 0 0 0 12 0m-6 6v4m-3 0h6',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-2-5h4l1 3 3 1 3 1v4l-3 1-1 3-1 3h-4l-1-3-3-1-3-1V8l3-1 1-3Z',
  leaf:'M12 21V10m0 6C3 16 2 8 3 3c6 0 10 4 9 10m0 2c0-8 4-12 10-12 1 7-2 12-10 12',
  drop:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Zm-5 13a5 5 0 0 0 5 5',
  battery:'M3 6h16v12H3Zm18 4v4M6 9v6m4-6v6m4-6v6',
  sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10Zm0-5v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',
  arrow:'M4 12h16m-6-6 6 6-6 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',
  check:'m5 12 4 4L19 6',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0m-4 4v.1',
  shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',play:'m8 4 12 8-12 8Z',pause:'M7 4v16m10-16v16',
  stop:'M5 5h14v14H5Z',camera:'M3 7h5l2-3h4l2 3h5v13H3Zm9 3a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7Z',
  pin:'M12 22S4 14 4 9a8 8 0 1 1 16 0c0 5-8 13-8 13Zm0-16a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',
  refresh:'M20 7a9 9 0 1 0 1 9M20 3v5h-5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',
  send:'m3 3 19 9-19 9 4-9Zm4 9h15',sound:'M3 9h4l5-5v16l-5-5H3Zm13-2a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16',
  info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 7v7m0-10v.1',close:'M5 5l14 14M5 19 19 5',probe:'M9 3h6v10H9Zm3 10v8m-4-6h8',
  cloud:'M7 18a5 5 0 1 1 0-10 6 6 0 0 1 11-1 5 5 0 0 1 0 10H7',link:'m10 8 2-2a5 5 0 0 1 7 7l-2 2m-3 1-2 2a5 5 0 0 1-7-7l2-2m2 6 8-8'
};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,extra='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
let state=createDemo(),page='overview',filter='open',storageReady=false,offlineReady=false,installPrompt=null,hubToken='',hubStatus='Not connected',saveChain=Promise.resolve(),toastTimer;
const farmer=createFarmerExperience({getState:()=>state,save:()=>persist(),render:()=>render(),toast,action:(a,v)=>doAction(a,v)});
const pages=[['overview','home','Overview'],['field','field','My field'],['alerts','alert','Alerts'],['rover','rover','Rover'],['assistant','voice','Farm guide']];
const sourceLabel=()=>state.source==='demo'?'Demo data':state.source==='live'?'Hub telemetry':'Imported data';
const freshLabel=z=>{const min=Math.max(0,Math.floor((Date.now()-Date.parse(z.updatedAt))/60000));return min<1?'Just now':min<60?`${min} min ago`:min<1440?`${Math.floor(min/60)} h ago`:`${Math.floor(min/1440)} d ago`;};
const timeLabel=at=>new Date(at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});
const openAlerts=()=>state.alerts.filter(a=>a.status==='open');
const disabled=()=>state.source!=='demo'?'disabled':'';
const statusLabel=()=>({ready:'Parked & ready',running:'Scouting · simulated',paused:'Paused',complete:'Demo complete',estop:'Simulated stop'})[state.rover.status]||'Read-only';
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5500);}
async function persist(){state.lastSavedAt=new Date().toISOString();const snapshot=structuredClone(state);saveChain=saveChain.then(()=>saveState(snapshot)).catch(()=>{storageReady=false;toast('Local save failed. Export your readings before closing this tab.');});return saveChain;}
function doAction(action,value){const result=act(state,action,value);if(result.error){toast(result.error);return false;}state=result.state;farmer.onUpdate();persist();render();return true;}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div>${action?`<div class="heading-actions">${action}</div>`:''}</div>`;}
function nav(mobile=false){return pages.map(([id,ic,label])=>`<a href="#${id}" ${page===id?'aria-current="page"':''} class="${page===id?'active':''}">${icon(ic)}<span>${mobile&&id==='assistant'?'Guide':label}</span>${!mobile&&id==='alerts'?`<span class="count">${openAlerts().length}</span>`:''}</a>`).join('');}
function metric(label,value,unit,note,ic,amber=false){return `<article class="metric"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${value}<span>${unit}</span></div><p class="metric-note ${amber?'amber':''}">${note}</p></article>`;}
function mapCard(title='Your field, at a glance') {
  return `<section class="card"><div class="card-head"><div><h2>${title}</h2><p>1 hectare · 6 observation zones · local-coordinate map</p></div><span class="badge">${icon('pin')} Maize</span></div><div class="tabs" role="group" aria-label="Map layer">${[['moisture','Soil moisture'],['weeds','Weeds'],['crop','Crop condition']].map(([id,label])=>`<button data-action="overlay" data-value="${id}" aria-pressed="${state.overlay===id}" class="${state.overlay===id?'selected':''}">${label}</button>`).join('')}</div><div class="map-wrap">${fieldMap()}</div><div class="map-bottom"><div class="legend">${state.overlay==='moisture'?'<span><i style="background:#efd6a1"></i> Below 22%</span><span><i style="background:#bad69b"></i> 22–34%</span><span><i style="background:#75a86c"></i> 35%+</span>':state.overlay==='weeds'?'<span><i style="background:#eed69f"></i> Inspect patch</span><span><i style="background:#bad69b"></i> Low demo cover</span>':'<span><i style="background:#b8d7a5"></i> Healthy flag</span><span><i style="background:#efd6a1"></i> Watch / review</span>'}</div><span>Tap a zone to inspect ${icon('arrow')}</span></div><div class="map-disclaimer">${state.source==='demo'?'Illustrative plot and simulated observations. Not a surveyed map or validated crop assessment.':'Read-only observations on an illustrative 2 × 3 grid. This is not a surveyed navigation map.'} ${!liveFresh(state)?'Hub telemetry is stale.':''}</div></section>`;
}
function fieldMap(){
  const rows=state.zones.map(z=>{
    const x=95+z.x*210,y=62+z.y*87,w=195,h=77,sel=z.id===state.selectedZone;
    const warning=state.overlay==='moisture'?z.moisture<22:state.overlay==='weeds'?z.weedCover>=12:z.crop!=='Healthy';
    const fill=warning?'#ecd7a7':z.moisture>=35&&state.overlay==='moisture'?'#8db97a':'#bfd6a4';
    const value=state.overlay==='moisture'?`${z.moisture}%`:state.overlay==='weeds'?`${z.weedCover}% cover`:z.crop;
    const stripe=Array.from({length:8},(_,i)=>`<path d="M${x+8} ${y+8+i*9}h${w-16}" stroke="${warning?'#c7ad73':'#91b07a'}" stroke-width="1.3" opacity=".48"/>`).join('');
    return `<g class="zone" tabindex="0" role="button" aria-label="Zone ${esc(z.id)}, ${esc(value)}" data-action="map-zone" data-value="${esc(z.id)}"><rect class="tile" x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="${fill}" stroke="${sel?'#1b6246':'#a4ba90'}" stroke-width="${sel?2.5:1}"/>${stripe}<rect x="${x+12}" y="${y+11}" width="33" height="21" rx="5" fill="#ffffffdf"/><text x="${x+28.5}" y="${y+25}" text-anchor="middle" font-size="10" font-weight="700" fill="#36543b">${esc(z.id)}</text><text x="${x+12}" y="${y+59}" font-size="18" font-weight="600" fill="#334e33">${esc(value)}</text><circle cx="${x+w-17}" cy="${y+20}" r="4" fill="${warning?'#b48837':'#5f8754'}"/>${isStale(z)?`<text x="${x+w-12}" y="${y+h-15}" text-anchor="end" font-size="9" fill="#884f1c">STALE</text>`:''}</g>`;
  }).join('');
  const rx=state.rover.zone==='Dock'?62:95+state.rover.x/100*405,ry=state.rover.zone==='Dock'?347:62+state.rover.y/100*251;
  return `<svg class="field-map" viewBox="0 0 600 395" role="group" aria-label="Illustrative one-hectare farm map"><defs><pattern id="grass" width="13" height="13" patternUnits="userSpaceOnUse"><path d="m3 7 1-2 1 2m5 5 1-2" stroke="#ccd9bd" stroke-width=".7" fill="none"/></pattern></defs><rect x="14" y="7" width="572" height="369" rx="13" fill="#f1f4e9"/><rect x="14" y="7" width="572" height="369" rx="13" fill="url(#grass)"/><path d="M51 16v309q0 22 24 22h468" stroke="#ddd8c3" stroke-width="19" fill="none"/><path d="M72 37h451v296H72Z" stroke="#afc599" stroke-dasharray="3 5" stroke-width="1" fill="none"/>${rows}<path class="route" d="M192 100H403v87H192v87h211" opacity=".55"/><g transform="translate(${rx} ${ry})"><circle r="14" fill="#ffffffc9"/><circle r="9" fill="#125b42" stroke="white" stroke-width="2"/><path d="m-3 3 3-7 3 7-3-1Z" fill="#ddefa7"/></g><g transform="translate(62 347)"><rect x="-17" y="-12" width="34" height="24" rx="6" fill="#fff" stroke="#bbbda4"/><path d="m-6 1 6-7 6 7v6h-12Z" fill="#6a8354"/></g><text x="85" y="351" font-size="9" fill="#768064">Dock · grid-primary charging</text><path d="M551 67V35m-5 6 5-7 5 7" fill="none" stroke="#7f9270" stroke-width="1.4"/><text x="551" y="27" text-anchor="middle" font-size="9" fill="#7f9270">N</text><path d="M452 359h48m-48-3v6m48-6v6" stroke="#879478"/><text x="476" y="374" text-anchor="middle" font-size="8" fill="#7e8c71">Illustrative 100 × 100 m</text></svg>`;
}
function alertsMini(){const list=openAlerts();return `<section class="card"><div class="card-head"><div><h2>Needs your attention</h2><p>Check the evidence before acting</p></div><span class="badge warn">${list.length} open</span></div><div class="alert-list">${list.length?list.slice(0,3).map(a=>`<article class="alert-row"><span class="alert-symbol ${a.severity==='high'?'high':''}">${icon(a.type==='moisture'?'drop':a.type==='weed'?'leaf':'camera')}</span><div><h3>${esc(a.title)}</h3><p>Zone ${esc(a.zone)} · ${esc(a.severity==='high'?'Priority check':'Review suggested')}</p><button data-action="inspect-alert" data-value="${esc(a.id)}">View recommendation →</button></div></article>`).join(''):'<p class="helper" style="padding:20px 0">All alerts reviewed. Routine scouting still matters.</p>'}</div><div class="card-footer"><a class="btn ghost" href="#alerts">All observations ${icon('arrow')}</a></div></section>`;}
function roverMini(){const r=state.rover;return `<section class="card"><div class="card-head"><div><h2>Your rover · AG-02</h2><p>${statusLabel()}</p></div><span class="dot"></span></div><div class="rover-preview"><img src="./assets/rover.png" alt="Agrova six-wheel agricultural rover engineering render" loading="lazy"><span class="badge demo">${state.source==='demo'?'Simulated twin':'Read-only telemetry'}</span></div><div class="rover-mini-metrics"><div><small>Battery</small><strong>${Math.round(r.battery)}%</strong></div><div><small>Solar assist</small><strong>${r.solarW} W</strong></div><div><small>Water tank</small><strong>${r.tankL.toFixed(2)} L</strong></div></div><div class="mini-progress"><p><span>Demo route progress</span><span>${Math.round(r.progress)}%</span></p><div class="progress"><span style="width:${r.progress}%"></span></div></div><div class="card-footer"><a href="#rover" class="btn ghost">Open rover workspace ${icon('arrow')}</a></div></section>`;}
function guideCallout(){return `<section class="guide-callout">${icon('voice')}<div><h3>Less jargon. Clearer decisions.</h3><p>Ask about soil, crops or your rover in English or Tamil.</p><a href="#assistant">Open your farm guide ${icon('arrow')}</a></div></section>`;}
function overview(){
  const stale=state.zones.some(z=>isStale(z));
  return heading('A clearer view of your farm.','Your observations, priorities and rover — in one place.',btn(`${icon('download')}<span>Export readings</span>`,'export'))+
    `<div class="welcome-band">${icon('leaf')}<div><h3>${stale?'Some samples need refreshing.':openAlerts().length?`${openAlerts().length} zones are worth a closer look today.`:'You have reviewed every current alert.'}</h3><p>${state.source==='demo'?'Explore the demo farm. No real rover commands or chemical recommendations are sent.':'Verify sample age and sensor calibration before making field decisions.'}</p></div><a class="btn small" href="#alerts">See priorities ${icon('arrow')}</a></div>`+
    `<section class="metrics" aria-label="Farm summary">${metric('Average soil moisture',averageMoisture(state),'%','Across sampled zones · not field-wide','drop')}${metric('Open observations',openAlerts().length,'',`${state.alerts.filter(a=>a.status==='reviewed').length} reviewed · ${sourceLabel().toLowerCase()}`,'alert',true)}${metric('Rover battery',Math.round(state.rover.battery),'%','12.8 V · replaceable LiFePO₄','battery')}${metric('Observation zones',state.zones.length,'','1 ha illustrative demo plot','field')}</section><div class="grid-two"><div class="stack">${mapCard()}${guideCallout()}</div><div class="stack">${alertsMini()}${roverMini()}</div></div>`;
}
function field(){const z=state.zones.find(z=>z.id===state.selectedZone)||state.zones[0];return heading('Understand each part of your field.','Select a zone to see its latest readings and recommendation.',btn(`${icon('download')}<span>Export readings</span>`,'export'))+`<div class="grid-two">${mapCard('A small field. Different needs.')}<section class="card card-pad zone-detail"><div class="zone-title"><div class="zone-tag">${esc(z.id)}</div><div><h2>${esc(z.name)}</h2><p>Sampled ${freshLabel(z)} · ${sourceLabel()}</p></div></div><span class="badge ${isStale(z)?'danger':'demo'}">${icon('clock')}${isStale(z)?'Stale observation':'Latest stored sample'}</span><div class="data-grid" style="margin-top:19px"><div><small>Soil moisture</small><strong>${z.moisture}<span> %</span></strong></div><div><small>Soil temperature</small><strong>${z.temperature.toFixed(1)}<span> °C</span></strong></div><div><small>Electrical conductivity</small><strong>${z.ec.toFixed(2)}<span> mS/cm</span></strong></div><div><small>Estimated weed cover</small><strong>${z.weedCover}<span> %</span></strong></div></div><div class="advice"><span class="eyebrow">Suggested next step</span><p>${esc(zoneAdvice(z))}</p></div><p class="helper">${esc(z.concern)} · confidence ${(z.confidence*100).toFixed(0)}%. ${state.source==='demo'?'Confidence and thresholds are illustrative; no AI model is running.':'Confidence is provided by the hub, not independently verified by this app.'}</p><div class="evidence">${icon('camera')}No field image attached. A flag alone is not proof of disease.</div>${btn(`${icon('probe')}Take demo sample here`,'sample',`data-value="${esc(z.id)}" ${disabled()}`)}${btn(`${icon('voice')}Explain this zone`,'explain-zone',`data-value="${esc(z.id)}"`,'ghost')}<p class="helper" style="margin-top:12px">Moisture % requires sensor- and soil-specific calibration. EC is not a direct nutrient measurement.</p></section></div>`;}
function alerts(){const list=state.alerts.filter(a=>filter==='all'||a.status===filter||filter==='high'&&a.severity==='high');return heading('Turn observations into next steps.','Review what was found. Decide what needs a field visit.')+`<div class="filterbar" role="group" aria-label="Filter alerts">${[['open','Open'],['reviewed','Reviewed'],['high','Priority'],['all','All observations']].map(([id,l])=>`<button data-action="filter" data-value="${id}" class="${filter===id?'selected':''}" aria-pressed="${filter===id}">${l} ${id==='open'?`· ${openAlerts().length}`:''}</button>`).join('')}</div><div class="alert-cards">${list.length?list.map(a=>`<article class="card alert-card"><div class="top"><span class="badge ${a.severity==='high'?'danger':'warn'}">${a.severity==='high'?'Priority check':'Review suggested'}</span><span class="helper">Zone ${esc(a.zone)}</span></div><h2>${esc(a.title)}</h2><p>${esc(a.detail)}</p><div class="evidence">${icon('info')}${state.source==='demo'?'Demo flag · no measured image evidence':'Hub/imported observation · verify in person'}</div><div class="actions">${btn(`${icon('field')}Inspect zone`,'inspect-zone',`data-value="${esc(a.zone)}"`)}${btn(`${icon('check')}${a.status==='open'?'Mark reviewed':'Reopen'}`,'ack',`data-value="${esc(a.id)}"`,'primary')}</div><p class="helper" style="min-height:0;margin-top:16px">${a.status==='reviewed'?'Reviewed locally. No treatment or cloud synchronization is implied.':'Observation time: '+esc(new Date(a.at).toLocaleString('en-IN'))}</p></article>`).join(''):`<div class="empty">${icon('check')}<h2>Nothing in this view.</h2><p>Try a different filter, or continue routine field scouting.</p></div>`}</div>`;}
function rover(){const r=state.rover,reason=movementReason(state),zone=state.selectedZone;return heading('One rover. A safer workflow.','Try the controls in simulation; live connections stay read-only.',`<a class="btn" href="https://sanjay-ai-ml.github.io/agrova/" target="_blank" rel="noopener">${icon('rover')}<span>Open 3D twin</span></a>`)+`<div class="welcome-band">${icon('shield')}<div><h3>${state.source==='demo'?'Simulation controls — not hardware controls':'Read-only telemetry mode'}</h3><p>This is not a physical emergency stop. Always use the rover’s hardwired safety switch in the field.</p></div></div><div class="metrics">${metric('Battery reserve',Math.round(r.battery),'%','Demo stop threshold · 20%','battery')}${metric('Solar assistance',r.solarW,'W','Grid-primary charging · solar supplement','sun')}${metric('Water remaining',r.tankL.toFixed(2),'L',`${r.waterMl} mL used in demo`,'drop')}${metric('Camera quality',Math.round(r.cameraQuality),'%','Simulated quality indicator','camera')}</div><div class="grid-two rover-main-grid"><div class="stack"><section class="card card-pad"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px"><div><h2>${statusLabel()}</h2><p class="helper" style="margin-top:5px">Row scouting · zone ${esc(r.zone)} · ${state.mission.samples} demo samples</p></div><span class="badge demo">AG-02</span></div><div class="mission-info"><span>Illustrative route progress</span><strong>${Math.round(r.progress)}%</strong></div><div class="progress"><span style="width:${r.progress}%"></span></div><div class="mission-controls">${btn(`${icon('play')}${r.status==='complete'?'Restart demo':'Start scouting'}`,'start',`${disabled()} ${r.status==='running'?'disabled':''}`,'primary')}${btn(`${icon('pause')}Pause`,'pause',`${disabled()} ${r.status!=='running'?'disabled':''}`)}${btn(`${icon('stop')}Simulated stop`,'estop',disabled(),'danger')}${r.status==='estop'?btn('Clear simulated stop','clearStop',disabled()):''}</div><label class="helper" for="speed">Demo playback speed</label><select id="speed" class="input" style="width:100px;margin-left:10px" ${disabled()}>${[1,3,5].map(n=>`<option value="${n}" ${state.mission.speed===n?'selected':''}>${n}×</option>`).join('')}</select><div class="safety ${reason?'':'good'}">${reason||'Motion interlocks clear. Probe is retracted; battery is above reserve.'}</div><div class="control-grid">${btn(`${icon('probe')}${r.probe==='retracted'?'Extend':'Retract'} probe`,'probe',disabled())}${btn(`${icon('camera')}Clean camera`,'clean',disabled())}${btn(`${icon('battery')}Replace battery`,'confirm-swap',disabled())}${btn(`${icon('drop')}25 mL water demo`,'confirm-water',disabled())}</div><p class="helper" style="margin-top:14px">Probe: ${r.probe} · cleaning reservoir: ${r.cleaningMl} mL · target zone: ${esc(zone)}. Water-only action requires confirmation and fresh evidence. No agricultural chemicals are controlled.</p></section>${mapCard('Scouting route · illustrative')}</div><div class="stack">${roverMini()}<section class="card"><div class="card-head"><div><h2>Activity log</h2><p>On-device history · no queued hardware commands</p></div></div><div class="log">${state.events.slice(0,15).map(e=>`<div class="log-item ${esc(e.kind)}"><time datetime="${esc(e.at)}">${timeLabel(e.at)}</time><span>${esc(e.text)}</span></div>`).join('')}</div></section><section class="card card-pad"><h3>Test the safety interlocks</h3><p class="helper" style="margin:9px 0 12px">Controlled faults affect the demo only.</p><div style="display:flex;gap:8px;flex-wrap:wrap">${btn(r.obstacle?'Clear obstacle':'Add obstacle','obstacle',disabled(),'small')}${btn('Low battery','lowBattery',disabled(),'small')}</div></section></div></div><div class="caption">AG-02 concept: 104 × 64 cm · six-wheel rocker-bogie · replaceable 12.8 V battery · solar assistance. Rover physics and field coverage are not validated by this app.</div>`;}
function quickQuestions(){return state.language==='ta'?['மண் ஈரப்பதம் எப்படி உள்ளது?','எங்கே களைகள் உள்ளன?','பேட்டரி நிலை என்ன?']:['How is my soil moisture?','Which zones have weeds?','How much battery is left?'];}
function assistant(){const ta=state.language==='ta';return heading('Your field, in plain language.','A local guide grounded in the readings on this device.')+`<div class="voice-layout"><section class="card"><div class="card-head"><div><h2>${ta?'உங்கள் பண்ணை உதவி':'Agrova farm guide'}</h2><p>Local, rule-based guidance · ${sourceLabel().toLowerCase()}</p></div><div class="language-switch" role="group" aria-label="Guide language">${[['en','English'],['ta','தமிழ்']].map(([id,l])=>`<button data-action="language" data-value="${id}" aria-pressed="${state.language===id}" class="${state.language===id?'selected':''}">${l}</button>`).join('')}</div></div><div class="chat" id="chat" aria-live="polite">${state.conversation.length?state.conversation.map((m,i)=>`<div class="message ${m.role==='user'?'user':'assistant'}" lang="${m.language||'en'}"><span class="message-label">${m.role==='user'?'You':'Agrova · local guide'}</span>${esc(m.text)}${m.role==='assistant'?btn(`${icon('sound')}Read aloud`,'speak',`data-value="${i}"`,'small'):''}</div>`).join(''):`<div class="chat-intro"><div class="voice-orb">${icon('voice')}</div><h2>${ta?'உங்கள் பண்ணையில் என்ன நடக்கிறது?':'What is happening in your field?'}</h2><p>${ta?'மண், களை, பயிர் அல்லது பேட்டரி பற்றி கேளுங்கள். இவை மாதிரி தரவுகள்.':'Start with a question about soil, weeds or your rover. Every answer tells you where the data comes from.'}</p><div class="quick-questions">${quickQuestions().map(q=>`<button data-action="ask" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div></div>`}</div><form class="composer" id="question-form"><input id="question" name="question" autocomplete="off" maxlength="500" aria-label="Ask the farm guide" placeholder="${ta?'உங்கள் கேள்வியை இங்கே எழுதுங்கள்…':'Ask about soil, crops or your rover…'}" required><button class="btn primary" type="submit" aria-label="Send question">${icon('send')}</button></form><div class="map-disclaimer">Offline text guidance works now. Read-aloud requires an installed on-device voice. Trained AI and microphone speech recognition are not connected.</div></section><div class="stack"><section class="card voice-explain"><h3>A guide you can understand.</h3><div class="feature-line">${icon('field')}<div><strong>Uses your current observations</strong><p>Answers come from stored zone readings and rover telemetry, with stale-data warnings.</p></div></div><div class="feature-line">${icon('shield')}<div><strong>Doesn’t act on your behalf</strong><p>No treatment prescriptions or voice-triggered hardware commands. You stay in control.</p></div></div><div class="feature-line">${icon('sound')}<div><strong>English & Tamil guidance</strong><p>Text works offline. Audio stays local and is available only if your device has a suitable voice.</p></div></div>${btn(`${icon('sound')}Read my farm summary`,'summary','', 'primary')}${btn('Stop speaking','stop-speech','','ghost')}<p class="helper" id="voice-status">${voiceStatus()}</p></section><section class="card card-pad"><span class="eyebrow">Next hardware milestone</span><h3 style="margin:10px 0">Connect the local voice hub.</h3><p class="helper">The planned hub runs Tamil speech recognition and grounded AI locally. This MVP deliberately does not pretend those models are already installed.</p><a class="btn ghost" href="#settings" style="margin-top:10px">Telemetry connection ${icon('arrow')}</a></section></div></div>`;}
function voiceStatus(){const voices=globalThis.speechSynthesis?.getVoices?.().filter(v=>v.localService&&v.lang.toLowerCase().startsWith(state.language))||[];return voices.length?`On-device ${state.language==='ta'?'Tamil':'English'} voice available.`:`No installed on-device ${state.language==='ta'?'Tamil':'English'} voice found. Text guidance remains available.`;}
function settings(){return heading('Keep your farm workspace connected.','Your data stays here unless you explicitly export it or contact a hub.')+`<div class="settings-grid"><section class="card settings-card"><h2>Read-only rover connection</h2><p>Connect to your own compatible farm hub. The app only fetches observations; it never sends motion, probe or spray commands.</p><form id="hub-form"><label class="label" for="hub-url">Telemetry endpoint URL</label><input class="input" id="hub-url" type="url" maxlength="500" placeholder="https://your-hub/api/v1/telemetry" value="${esc(state.gatewayUrl)}" required autocomplete="off"><label class="label" for="hub-token">Access token (this session only)</label><input class="input" id="hub-token" type="password" maxlength="2048" placeholder="Optional bearer token" autocomplete="off"><div class="actions"><button class="btn primary" type="submit">${icon('refresh')}Fetch observations</button>${btn('Forget connection','disconnect')}</div></form><p class="helper" id="hub-status">${esc(hubStatus)}</p><p class="helper">Requires a compatible JSON response and CORS permission for this origin. HTTPS pages cannot connect to an insecure HTTP farm hub. No automatic polling or background command replay.</p></section><section class="card settings-card"><h2>Bring your readings with you.</h2><p>Import a telemetry snapshot without internet access, or export current observations as a portable JSON file.</p><label class="label" for="import-file">Import telemetry JSON · up to 1 MB</label><input id="import-file" type="file" accept="application/json,.json"><div class="actions">${btn(`${icon('download')}Export observations`,'export')}${btn('Download sample JSON','sample-json')}</div><p class="helper">Imports are validated and displayed read-only. Alert reviews and conversations stay in this browser; JSON export contains telemetry only.</p><pre>schema: agrova.telemetry.v1\nmoisture: % · temperature: °C\nec: mS/cm · weedCover: %\nrover: battery % · tankL · solarW\nupdatedAt: ISO 8601 timestamp</pre></section><section class="card settings-card"><h2>Offline & on this device</h2><p>Load the app once while connected. Its core screens and stored observations then work offline on supported browsers.</p><div class="status-line"><span>App shell</span><strong>${offlineReady?'Cached for offline use':'Preparing offline cache…'}</strong></div><div class="status-line"><span>Local persistence</span><strong>${storageReady?'IndexedDB available':'Session-only · export before closing'}</strong></div><div class="status-line"><span>Current source</span><strong>${sourceLabel()}</strong></div><div class="status-line"><span>Last saved</span><strong>${state.lastSavedAt?timeLabel(state.lastSavedAt):'This session'}</strong></div><div class="actions">${btn(`${icon('download')}Install app`,'install')}${btn('Request durable storage','durable')}</div><p class="install-note">Android Chrome: browser menu → Add to Home screen / Install app. iPhone Safari: Share → Add to Home Screen. This is an installable web app, not an APK. Private hosting sign-in may require connectivity when the session expires.</p><div class="danger-zone">${btn('Reset to fresh demo','reset','','danger')}<p class="helper">Replaces this browser’s saved observations, reviews and chat. Export any readings you want to keep first.</p></div></section><section class="card settings-card"><h2>What is real in this version?</h2><p>The interface, offline storage, alert reviews, file transfer and telemetry validation work. Agronomic values and rover controls start in an explicitly labelled simulation.</p><div class="feature-line">${icon('leaf')}<div><strong>No unverified AI claims</strong><p>This build does not run crop detection or a trained language model. It presents simulated or hub-provided observations.</p></div></div><div class="feature-line">${icon('battery')}<div><strong>Grid-primary, solar-assisted</strong><p>Replaceable rover battery. Soil microbial-fuel-cell sensor nodes remain a research concept; electrode voltage alone does not determine soil health.</p></div></div><div class="feature-line">${icon('shield')}<div><strong>Safe integration boundary</strong><p>Hardware commands, calibrated thresholds, real GPS mapping and autonomous navigation require separate validated integrations.</p></div></div><a class="btn" href="https://sanjay-ai-ml.github.io/agrova/" target="_blank" rel="noopener">View the existing 3D twin ${icon('arrow')}</a></section></div>`;}
function render(){
  if(FARMER_PAGES.includes(page)){document.querySelector('#app').innerHTML=farmer.render(page);return;}
  document.documentElement.lang='en';
  const online=navigator.onLine;
  document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#overview"><img src="./assets/icon.svg" alt=""><div><strong>Agrova</strong><small>Farmer workspace</small></div></a><div class="side-label">Your farm</div><nav class="nav" aria-label="Main navigation">${nav()}</nav><div class="side-bottom"><div class="offline-card"><strong><span class="dot"></span>${offlineReady?'Made to work offline':'Local-first workspace'}</strong><p>Field insights. Less guesswork.<br>Your decisions stay yours.</p></div><a href="#settings" class="btn ghost" style="color:#c7dace;justify-content:flex-start">${icon('settings')}Connections & settings</a></div></aside><div class="content"><header class="topbar"><div class="farm-name">${icon('field')}<div>${esc(state.farm.name)}<small>${esc(state.farm.locality)}</small></div></div><div class="top-actions"><span class="badge demo">${state.source==='demo'?'<span class="dot"></span>':icon('link')}${sourceLabel()}</span><span class="badge connection-badge">${icon('wifi')}${online?'Device online':'Device offline'}</span><a href="#settings" class="icon-btn" aria-label="Connections and settings">${icon('settings')}</a><span class="avatar" aria-label="Local farm workspace">AG</span></div></header><main class="main" id="main">${({overview,field,alerts,rover,assistant,settings})[page]()}${page==='rover'?'':`<footer class="caption">Agrova · Built for small fields, clearer decisions and a farmer in control. ${state.source==='demo'?'Simulated data throughout.':''}</footer>`}</main></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav(true)}</nav></div>`;
  if(page==='settings')document.querySelector('.settings-grid').insertAdjacentHTML('beforeend',farmer.advancedSettings());
  document.querySelector('.side-bottom').insertAdjacentHTML('afterbegin','<a class="btn lime" href="#home" style="width:100%;margin-bottom:14px">Farm dashboard</a>');
  if(page==='assistant'&&state.conversation.length){const chat=document.querySelector('#chat');chat.scrollTop=chat.scrollHeight;}
}
function route(){const hash=location.hash.slice(1).split('?')[0];page=[...FARMER_PAGES,'overview','field','alerts','rover','assistant','settings'].includes(hash)?hash:'home';render();window.scrollTo(0,0);}
function modal(title,text,confirmLabel,callback){const d=document.querySelector('#dialog');d.className='';d.innerHTML=`<span class="eyebrow">Farmer confirmation</span><h2 id="dialog-title">${esc(title)}</h2><p>${esc(text)}</p><div class="dialog-actions">${btn('Cancel','close-dialog')}${btn(esc(confirmLabel),'confirm-dialog','','primary')}</div>`;d.querySelector('[data-action=confirm-dialog]').onclick=()=>{d.close();callback();};d.showModal();}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('JSON file prepared. Save it somewhere you can find again.');}
function ask(question){const q=question.trim().slice(0,500);if(!q)return;state.conversation.push({role:'user',text:q,language:state.language},{role:'assistant',text:assistantAnswer(q,state),language:state.language});state.conversation=state.conversation.slice(-40);persist();render();}
function speak(text,language=state.language){
  if(!globalThis.speechSynthesis){toast('Speech is unavailable in this browser. Read the text guidance instead.');return;}
  const voice=speechSynthesis.getVoices().find(v=>v.localService&&v.lang.toLowerCase().startsWith(language));
  if(!voice){toast(`Install an on-device ${language==='ta'?'Tamil':'English'} voice in your device settings. No cloud voice is used.`);return;}
  speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.voice=voice;utterance.lang=voice.lang;utterance.rate=.95;utterance.onerror=()=>toast('Read-aloud could not complete. Text guidance is still available.');speechSynthesis.speak(utterance);toast('Reading aloud using your installed on-device voice.');
}
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,value=el.dataset.value;
  switch(action){
    case 'map-zone': state.selectedZone=value;persist();if(page==='overview')location.hash='field';else render();break;
    case 'inspect-zone': state.selectedZone=value;persist();location.hash='field';break;
    case 'inspect-alert': {const a=state.alerts.find(a=>a.id===value);if(a){state.selectedZone=a.zone;persist();location.hash='field';}break;}
    case 'filter':filter=value;render();break;
    case 'export':download(exportTelemetry(state),`agrova-${state.source}-${new Date().toISOString().slice(0,10)}.json`);break;
    case 'sample-json':download(exportTelemetry(createDemo()),'agrova-sample-telemetry.json');break;
    case 'confirm-water': {const z=state.zones.find(z=>z.id===state.selectedZone),reason=waterReason(state,z);if(reason){toast(reason);break;}modal('Approve a water-only demo?',`This simulates 25 mL in zone ${z.id}. It does not water a real field, apply pesticides or change the stored soil moisture reading.`,'Approve 25 mL demo',()=>{if(doAction('water',{zone:z.id,approved:true}))toast('Water-only action recorded in the simulated activity log.');});break;}
    case 'confirm-swap':modal('Replace the demo battery?','For a real cartridge: park, stop all actuators, isolate power, retract the probe, insert the replacement using its guides and verify the latch. This app only simulates that sequence.','Simulate replacement',()=>{if(doAction('swap'))toast('Demo battery replaced. No physical hardware was controlled.');});break;
    case 'reset':modal('Start again with demo data?','This replaces saved observations, reviews and conversations on this browser. Export your readings first if you need them.','Reset local demo',()=>{farmer.stop();state=createDemo();farmer.initialize();hubToken='';hubStatus='Not connected';persist();location.hash='home';render();toast('Fresh demo loaded. Previous local data was replaced.');});break;
    case 'ask':ask(el.dataset.question||'');break;
    case 'speak':{const m=state.conversation[Number(value)];if(m?.role==='assistant')speak(m.text,m.language);break;}
    case 'summary':speak(assistantAnswer(state.language==='ta'?'மண் ஈரப்பதம்':'soil moisture',state));break;
    case 'stop-speech':globalThis.speechSynthesis?.cancel();break;
    case 'explain-zone':{const z=state.zones.find(z=>z.id===value);state.conversation.push({role:'assistant',text:`${sourceLabel()}. Zone ${z.id}: ${z.moisture}% soil moisture, ${z.weedCover}% estimated weed cover. ${zoneAdvice(z)}`,language:'en'});persist();location.hash='assistant';break;}
    case 'install':if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;toast(choice.outcome==='accepted'?'Installation requested.':'You can install later from your browser menu.');installPrompt=null;}else toast('Use your browser menu → Install app / Add to Home screen. iPhone: Share → Add to Home Screen.');break;
    case 'durable':{const ok=await navigator.storage?.persist?.();toast(ok?'Browser granted persistent storage. Export backups too.':'Durable storage was not granted. The browser may clear data; export backups.');break;}
    case 'disconnect':hubToken='';state.gatewayUrl='';hubStatus='Connection forgotten. Stored readings remain read-only.';persist();render();break;
    case 'close-dialog':document.querySelector('#dialog').close();break;
    case 'confirm-dialog':break;
    default:if(doAction(action,value)&&action!=='overlay'&&action!=='language'&&action!=='zone')toast(action==='sample'?'Demo sample stored; rover positioned in the selected zone.':action==='ack'?'Review status saved on this device.':'Demo action recorded.');
  }
});
document.addEventListener('keydown',e=>{const el=e.target.closest('g[data-action]');if(el&&['Enter',' '].includes(e.key)){e.preventDefault();el.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('submit',async e=>{
  if(e.target.id==='question-form'){e.preventDefault();ask(new FormData(e.target).get('question')||'');}
  if(e.target.id==='hub-form'){
    e.preventDefault();const endpoint=document.querySelector('#hub-url').value.trim();hubToken=document.querySelector('#hub-token').value.trim();
    try{
      const url=new URL(endpoint);
      if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw new Error('Use an HTTP(S) endpoint without embedded credentials.');
      if(location.protocol==='https:'&&url.protocol==='http:')throw new Error('This HTTPS app requires an HTTPS hub; insecure farm HTTP is blocked.');
      const submit=e.target.querySelector('[type=submit]');submit.disabled=true;document.querySelector('#hub-status').textContent='Fetching a read-only observation snapshot…';
      const response=await fetch(url,{method:'GET',headers:{Accept:'application/json',...(hubToken?{Authorization:`Bearer ${hubToken}`}:{})},cache:'no-store',credentials:'omit',redirect:'error',signal:AbortSignal.timeout(10000)});
      if(!response.ok)throw new Error(`Hub responded ${response.status}. Check endpoint access.`);
      if(Number(response.headers.get('content-length')||0)>1048576)throw new Error('Hub payload exceeds 1 MB.');
      const text=await response.text();if(text.length>1048576)throw new Error('Hub payload exceeds 1 MB.');
      state=importTelemetry(state,JSON.parse(text),'live');state.gatewayUrl=url.href;farmer.onUpdate();hubStatus=`Connected. Snapshot fetched at ${timeLabel(new Date().toISOString())}. No hardware commands sent.`;await persist();render();toast('Hub readings loaded in read-only mode.');
    }catch(error){hubStatus=`Not connected: ${error.message==='Failed to fetch'?'Network or CORS failure. Stored observations are unchanged.':error.message}`;render();toast(hubStatus);}
  }
});
document.addEventListener('change',async e=>{
  if(e.target.id==='speed')doAction('speed',e.target.value);
  if(e.target.id==='import-file'){
    const file=e.target.files?.[0];if(!file)return;
    try{if(file.size>1048576)throw new Error('Choose a JSON snapshot smaller than 1 MB.');const incoming=JSON.parse(await file.text());const next=importTelemetry(state,incoming,'imported');modal('Use these imported observations?','Validated readings will replace the current demo/telemetry snapshot and pause the demo. Controls become read-only. Your local history remains.','Import read-only data',()=>{state=next;farmer.onUpdate();persist();render();toast('Validated readings imported. Rover controls are disabled.');});}catch(error){toast(`Import rejected: ${error.message}`);e.target.value='';}
  }
});
window.addEventListener('hashchange',route);
window.addEventListener('online',()=>{render();toast('Device connectivity restored. Rover telemetry is not refreshed automatically.');});
window.addEventListener('offline',()=>{render();toast('Device offline. Showing the latest locally stored readings.');});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
globalThis.speechSynthesis?.addEventListener('voiceschanged',()=>{const status=document.querySelector('#voice-status');if(status)status.textContent=voiceStatus();});
try{await openStore();storageReady=true;const saved=await readState();if(saved?.schema==='agrova.telemetry.v1'){state={...createDemo(),...saved};if(state.rover.status==='running'){state.rover.status='paused';state.events.unshift({id:'reload-'+Date.now(),at:new Date().toISOString(),text:'Reload paused the demo; no motion automatically resumed.',kind:'info'});}}farmer.initialize();await persist();}catch(error){farmer.initialize();storageReady=false;setTimeout(()=>toast(error.message),800);}
route();
if('serviceWorker' in navigator&&window.isSecureContext){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;farmer.incoming();if(page==='settings')render();else{const label=document.querySelector('.offline-card strong');if(label)label.innerHTML='<span class="dot"></span>Made to work offline';}}).catch(()=>toast('Offline cache unavailable in this browser. Keep a connection or run on localhost.'));}
setInterval(()=>{if(state.rover.status==='running'&&state.source==='demo'){const result=act(state,'tick');state=result.state;farmer.onUpdate();persist();if(['rover','overview','machine','home'].includes(page))render();}},1000);
document.addEventListener('change',e=>{if(e.target.id==='poll-hub'){state.farmer.polling=e.target.checked;persist();}});
let hubPolling=false;
setInterval(async()=>{if(!state.farmer.polling||state.source!=='live'||!state.gatewayUrl||!navigator.onLine||document.visibilityState!=='visible'||hubPolling)return;hubPolling=true;try{const r=await fetch(state.gatewayUrl,{headers:{Accept:'application/json',...(hubToken?{Authorization:`Bearer ${hubToken}`}:{})},credentials:'omit',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(10000)});if(!r.ok)throw new Error('Hub unavailable');const raw=await r.text();if(raw.length>1048576)throw new Error('Snapshot too large');state=importTelemetry(state,JSON.parse(raw),'live');farmer.onUpdate();persist();if(FARMER_PAGES.includes(page)||page==='overview')render();}catch{hubStatus='Latest refresh failed. Showing stored observations.';}finally{hubPolling=false;}},30000);
document.addEventListener('submit',async event=>{if(event.target.id!=='push-form')return;event.preventDefault();const status=document.querySelector('#push-status');try{const endpoint=new URL(document.querySelector('#push-url').value);if(endpoint.protocol!=='https:'||endpoint.username||endpoint.password)throw new Error('Use an HTTPS endpoint without embedded credentials.');const key=document.querySelector('#vapid-key').value.trim();if(!/^[A-Za-z0-9_-]+$/.test(key))throw new Error('Invalid VAPID public key.');const normalized=key.replace(/-/g,'+').replace(/_/g,'/');const decoded=Uint8Array.from(atob(normalized+'='.repeat((4-normalized.length%4)%4)),c=>c.charCodeAt(0));if(decoded.length!==65)throw new Error('Expected a 65-byte VAPID public key.');if(!('Notification' in globalThis)||await Notification.requestPermission()!=='granted')throw new Error('Notification permission was not granted.');const reg=await navigator.serviceWorker.ready;if(!reg.pushManager)throw new Error('Web Push is unsupported.');const subscription=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:decoded});const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json',...(hubToken?{Authorization:`Bearer ${hubToken}`}:{})},body:JSON.stringify({schema:'agrova.push-subscription.v1',subscription:subscription.toJSON(),language:state.farmer.language}),credentials:'omit',redirect:'error',signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error(`Hub registration failed (${response.status}).`);state.farmer.phoneNotifications=true;persist();status.textContent='Subscription registered with the selected hub. Sender-side delivery and phone testing are still required.';}catch(error){status.textContent=error.message;}});
